node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
// Also check if there are flights with dates_json containing 2026-10-15 but different departure times
const flights = db.prepare(\"SELECT * FROM flights WHERE origin = 'JFK' AND destination = 'LHR' AND dates_json LIKE '%2026-10-15%'\").all();
flights.forEach(f => {
  const dates = JSON.parse(f.dates_json);
  const cabin = JSON.parse(f.cabin_prices_json);
  console.log('Flight ID:', f.flight_id);
  console.log('Departure:', f.departure_time);
  console.log('Arrival:', f.arrival_time);
  console.log('Stops:', f.stops);
  console.log('Status:', f.status);
  console.log('Cabin Prices:', JSON.stringify(cabin, null, 2));
  console.log('Date Details:', JSON.stringify(dates, null, 2));
  console.log('---');
});
console.log('Total matching flights for 2026-10-15:', flights.length);
"

